//! Git helpers and crash-safe workspace snapshots used by the safe-fix loop.

use crate::Result;
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

pub fn is_git_repo(path: &Path) -> bool {
    path.join(".git").is_dir() || path.join(".git").is_file()
}

/// Files that are generated by codesafe itself and must not make a tree look
/// dirty (otherwise repeated `fix` runs would refuse to start).
fn is_generated_artifact(line: &str) -> bool {
    let path = line.get(3..).unwrap_or(line).trim();
    path == "report.md"
        || path == "report.json"
        || path == "AGENT_TASK.md"
        || path.starts_with(".codesafe/")
        || path.starts_with(".codeguard/")
        || path.ends_with("/report.md")
        || path.ends_with("/report.json")
}

pub fn is_dirty(path: &Path) -> Result<bool> {
    if !is_git_repo(path) {
        return Ok(false);
    }
    let output = std::process::Command::new("git")
        .args(["-C", path.to_str().unwrap_or("."), "status", "--porcelain"])
        .output()
        .map_err(|e| crate::Error::Git(format!("git status: {e}")))?;
    let dirty = String::from_utf8_lossy(&output.stdout)
        .lines()
        .any(|line| !line.trim().is_empty() && !is_generated_artifact(line));
    Ok(dirty)
}

/// Commit the current tree and return the *new* commit hash.
///
/// Returning the new hash is critical: the safe-fix loop reverts to this commit
/// when a fix fails, which preserves any pre-existing changes that were captured
/// by the checkpoint. Returning the pre-checkpoint hash would discard them.
pub fn checkpoint(path: &Path) -> Result<String> {
    let before = current_head(path)?;
    commit(
        path,
        &format!("codesafe: checkpoint before safe-fix loop ({before})"),
    )?;
    current_head(path)
}

pub fn commit(path: &Path, message: &str) -> Result<()> {
    // Never capture codesafe's own artifacts in a checkpoint/fix commit.
    let status = std::process::Command::new("git")
        .args([
            "-C",
            path.to_str().unwrap_or("."),
            "add",
            "-A",
            "--",
            ".",
            ":(exclude).codesafe",
            ":(exclude).codeguard",
            ":(exclude)report.md",
            ":(exclude)report.json",
            ":(exclude)AGENT_TASK.md",
            ":(exclude)target",
            ":(exclude).venv",
            ":(exclude)venv",
            ":(exclude)node_modules",
            ":(exclude)__pycache__",
            ":(exclude).mypy_cache",
            ":(exclude).pytest_cache",
            ":(exclude).ruff_cache",
            ":(exclude)dist",
        ])
        .status()
        .map_err(|e| crate::Error::Git(format!("git add: {e}")))?;
    if !status.success() {
        return Err(crate::Error::Git("git add failed".into()));
    }
    // Only commit if there is something staged.
    let diff = std::process::Command::new("git")
        .args([
            "-C",
            path.to_str().unwrap_or("."),
            "diff",
            "--cached",
            "--quiet",
        ])
        .status()
        .map_err(|e| crate::Error::Git(format!("git diff: {e}")))?;
    if diff.success() {
        return Ok(()); // nothing to commit
    }
    let status = std::process::Command::new("git")
        .args(["-C", path.to_str().unwrap_or("."), "commit", "-m", message])
        .status()
        .map_err(|e| crate::Error::Git(format!("git commit: {e}")))?;
    if status.success() {
        Ok(())
    } else {
        Err(crate::Error::Git("git commit failed".into()))
    }
}

pub fn current_head(path: &Path) -> Result<String> {
    let output = std::process::Command::new("git")
        .args(["-C", path.to_str().unwrap_or("."), "rev-parse", "HEAD"])
        .output()
        .map_err(|e| crate::Error::Git(format!("git rev-parse: {e}")))?;
    if !output.status.success() {
        return Err(crate::Error::Git(
            String::from_utf8_lossy(&output.stderr).trim().to_string(),
        ));
    }
    Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
}

pub fn tree_hash(path: &Path) -> Result<String> {
    let output = std::process::Command::new("git")
        .args([
            "-C",
            path.to_str().unwrap_or("."),
            "rev-parse",
            "HEAD^{tree}",
        ])
        .output()
        .map_err(|e| crate::Error::Git(format!("git rev-parse tree: {e}")))?;
    Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
}

pub fn revert_to(path: &Path, reference: &str) -> Result<()> {
    let status = std::process::Command::new("git")
        .args([
            "-C",
            path.to_str().unwrap_or("."),
            "reset",
            "--hard",
            reference,
        ])
        .status()
        .map_err(|e| crate::Error::Git(format!("git reset: {e}")))?;
    if status.success() {
        Ok(())
    } else {
        Err(crate::Error::Git("git reset failed".into()))
    }
}

/// Files changed relative to HEAD (porcelain paths, repository-relative).
pub fn changed_files(path: &Path) -> Result<Vec<PathBuf>> {
    if !is_git_repo(path) {
        return Ok(Vec::new());
    }
    let output = std::process::Command::new("git")
        .args([
            "-C",
            path.to_str().unwrap_or("."),
            "status",
            "--porcelain",
            "--untracked-files=all",
        ])
        .output()
        .map_err(|e| crate::Error::Git(format!("git status: {e}")))?;
    let mut files = Vec::new();
    for line in String::from_utf8_lossy(&output.stdout).lines() {
        if line.trim().is_empty() {
            continue;
        }
        let p = line.get(3..).unwrap_or("").trim();
        if !p.is_empty() {
            files.push(PathBuf::from(p));
        }
    }
    Ok(files)
}

/// Read a file as it exists at `reference` (e.g. `HEAD`).
pub fn file_at_revision(path: &Path, reference: &str, file: &str) -> Result<Option<String>> {
    if !is_git_repo(path) {
        return Ok(None);
    }
    let spec = format!("{reference}:{file}");
    let output = std::process::Command::new("git")
        .args(["-C", path.to_str().unwrap_or("."), "show", &spec])
        .output()
        .map_err(|e| crate::Error::Git(format!("git show: {e}")))?;
    if !output.status.success() {
        return Ok(None);
    }
    Ok(Some(String::from_utf8_lossy(&output.stdout).to_string()))
}

/// A best-effort workspace snapshot used when the repository is not a git repo.
///
/// The snapshot copies all non-ignored files into a temporary directory and
/// records their hashes. `restore()` overlays the copies back, so a failed fix
/// cannot leave a non-git workspace half-modified.
#[derive(Debug)]
pub struct Snapshot {
    root: PathBuf,
    backup_dir: PathBuf,
    files: BTreeMap<String, String>,
}

impl Snapshot {
    pub fn create(root: &Path) -> Result<Self> {
        let backup_dir = std::env::temp_dir().join(format!(
            "codesafe-snapshot-{}-{}",
            std::process::id(),
            monotonic_nonce()
        ));
        std::fs::create_dir_all(&backup_dir)
            .map_err(|e| crate::Error::Git(format!("snapshot dir: {e}")))?;
        let mut files = BTreeMap::new();
        let mut total: u64 = 0;
        const MAX_TOTAL: u64 = 512 * 1024 * 1024;
        for file in crate::scan::all_files(root) {
            let rel = crate::scan::relative_to(root, &file);
            let meta = match std::fs::metadata(&file) {
                Ok(m) => m,
                Err(_) => continue,
            };
            if !meta.is_file() {
                continue;
            }
            total = total.saturating_add(meta.len());
            if total > MAX_TOTAL {
                break;
            }
            let dest = backup_dir.join(&rel);
            if let Some(parent) = dest.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            if std::fs::copy(&file, &dest).is_ok() {
                files.insert(rel, crate::types::hash_file(&file).unwrap_or_default());
            }
        }
        Ok(Self {
            root: root.to_path_buf(),
            backup_dir,
            files,
        })
    }

    /// True when any tracked file differs from the snapshot (or new files exist).
    pub fn changed(&self) -> bool {
        let current = crate::scan::all_files(&self.root);
        if current.iter().any(|f| {
            let rel = crate::scan::relative_to(&self.root, f);
            !self.files.contains_key(&rel)
        }) {
            return true;
        }
        self.files.iter().any(|(rel, old_hash)| {
            let path = self.root.join(rel);
            crate::types::hash_file(&path)
                .map(|h| &h != old_hash)
                .unwrap_or(true)
        })
    }

    /// Restore every snapshotted file back into the workspace.
    pub fn restore(&self) -> Result<()> {
        for rel in self.files.keys() {
            let src = self.backup_dir.join(rel);
            let dest = self.root.join(rel);
            if let Some(parent) = dest.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            std::fs::copy(&src, &dest)
                .map_err(|e| crate::Error::Git(format!("restoring snapshot file {rel}: {e}")))?;
        }
        Ok(())
    }

    /// Remove the temporary backup directory.
    pub fn cleanup(&self) {
        let _ = std::fs::remove_dir_all(&self.backup_dir);
    }
}

impl Drop for Snapshot {
    fn drop(&mut self) {
        self.cleanup();
    }
}

fn monotonic_nonce() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn non_git_dir_is_not_repo() {
        let dir = std::env::temp_dir().join(format!("codesafe-git-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        assert!(!is_git_repo(&dir));
        assert!(!is_dirty(&dir).unwrap());
    }

    #[test]
    fn snapshot_restores_modified_and_added_files() {
        let dir =
            std::env::temp_dir().join(format!("codesafe-snapshot-test-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("a.txt"), b"original").unwrap();
        let snap = Snapshot::create(&dir).unwrap();
        std::fs::write(dir.join("a.txt"), b"changed").unwrap();
        std::fs::write(dir.join("b.txt"), b"new").unwrap();
        assert!(snap.changed());
        snap.restore().unwrap();
        assert_eq!(
            std::fs::read_to_string(dir.join("a.txt")).unwrap(),
            "original"
        );
        // Newly created files are not deleted, but the tracked file is restored.
        assert!(dir.join("b.txt").exists());
    }

    #[test]
    fn snapshot_reports_unchanged() {
        let dir =
            std::env::temp_dir().join(format!("codesafe-snapshot-clean-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("a.txt"), b"same").unwrap();
        let snap = Snapshot::create(&dir).unwrap();
        assert!(!snap.changed());
    }

    #[test]
    fn generated_artifacts_are_not_dirty() {
        assert!(is_generated_artifact("?? report.md"));
        assert!(is_generated_artifact("?? .codesafe/agent-brief.json"));
        assert!(!is_generated_artifact(" M src/lib.rs"));
    }
}
